/// <summary>
/// This is business logic class
/// CB387_DallasPickListRegistration
/// </summary>
final class METPickingListRegistrationPostingJob
{
}

Method.Source:
    //Map selectedLines; //key wmsOrderTrans.recId, Value: WMSOrderTrans.orderid;//used to hit best index

    /// <summary>
    /// This method hold the posting logic
    /// </summary>
    /// <param name = "_contract">Contract</param>
    public void postPickListRegistration(METDallasPicklistRegContract _contract)
    {
        #OCCRetryCount

        container       conOrdTrans;
        WMSOrderTrans   orderTrans;
        int             i;

        conOrdTrans = _contract.parmConOrderTrans();
        
        //WMSOrderTransType::finishPickingLinesMultiTTS(conOrdTrans);

        for (i=1; i <= conlen(conOrdTrans); i++)
        {
            try
            {
                ttsbegin;
                orderTrans = conpeek(conOrdTrans, i);
                var selectedLine = new Map(Types::int64,Types::Container);
                selectedLine.insert(orderTrans.RecId, [orderTrans.orderId, orderTrans.RecVersion]);

                WMSOrderTransType::finishPickingLinesMulti(selectedLine.pack(), '', orderTrans.wmsPickingRoute().OperatorWorker);
                orderTrans.selectForUpdate(true);

                // Bug 193337: CB616 - "Trigger cancellation" button not triggering TMS processing
                // reread the record otherwise the current buffer still has the previous status
                orderTrans.reread();

                // Bug 246341: CB387 - Dallas Picklist Registration - zero pick quantity is updating the picking list registration when importing using data entity Picklist registration entity
                // For 0 pick, status updated to cancel, we also need to cancel the SO line deliver remainder.
                // For picking list with multiple lines, status is updated to picked first, then when everything is processed status is updated to completed
                if (orderTrans.expeditionStatus != WMSExpeditionStatus::Activated)
                {
                    // Bug 193337: CB616 - "Trigger cancellation" button not triggering TMS processing
                    // moving the trigger to cancel remainder qty from WMSOrderTrans.update to after the "update selected button"
                    // to bypass error "The quantity cannot be reduced from item 10000016 and lot id 2000-125761. 
                    // The number of inventory transactions on order is too low because the quantity or part of it is referenced by an output order or a production order or is marked against other transactions."
                    orderTrans.metShortPickDeliveryReminderUpd();

                    orderTrans.METPickedQtyProcessed = NoYes::Yes;
                    orderTrans.update();   

                    if (orderTrans.inventTransType == InventTransType::TransferOrderShip)
                    {
                        //Added for Task 282558: CB913/CB162 - Campbells -Integration - Campbells Transfer Order Receipt
                        METCampbellTransferOrderProcessor::construct().processCampbellsTransferOrder(InventTransferTable::find(orderTrans.inventTransRefId));
                    }
                }
                
                ttscommit;
            }
            catch(Exception::Deadlock)
            {
                retry;
            }
            catch (Exception::UpdateConflict)
            {
                if (appl.ttsLevel() == 0)
                {
                    if (xSession::currentRetryCount() >= #RetryNum)
                    {
                        throw Exception::UpdateConflictNotRecovered;
                    }
                    else
                    {
                        retry;
                    }
                }
                else
                {
                    throw Exception::UpdateConflict;
                }
            }
            // Bug 246341: CB387 - Dallas Picklist Registration - zero pick quantity is updating the picking list registration when importing using data entity Picklist registration entity
            // Poor exception handling, if any errors go to the next picking list line to register
            catch(Exception::Error)
            {
                exceptionTextFallThrough();
            }
        }

    }
